  enrollment_id INT,
  provider VARCHAR(50) DEFAULT 'flutterwave',
  tx_ref VARCHAR(100) UNIQUE NOT NULL,
  provider_transaction_id VARCHAR(100),
  amount DECIMAL(12, 2) NOT NULL,
  currency VARCHAR(10) DEFAULT 'KES',
  status VARCHAR(50) DEFAULT 'pending' CHECK (status IN ('pending', 'successful', 'failed', 'cancelled')),
  payment_link TEXT,
  raw_response JSON,
  verified_at DATETIME,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (competition_id) REFERENCES competitions(id) ON DELETE CASCADE,
  FOREIGN KEY (learner_id) REFERENCES learners(id) ON DELETE CASCADE,
  FOREIGN KEY (enrollment_id) REFERENCES competition_enrollments(id) ON DELETE SET NULL
);

CREATE TABLE IF NOT EXISTS competition_results (
  id INT AUTO_INCREMENT PRIMARY KEY,
  competition_id INT,
  learner_id INT,
  result_stage VARCHAR(50) DEFAULT 'final' CHECK (result_stage IN ('practice', 'final')),
  learner_grade VARCHAR(50),
  competition_type VARCHAR(50) DEFAULT 'quiz',
  quiz_score DECIMAL(6, 2),
  typing_wpm DECIMAL(6, 2),
  typing_accuracy DECIMAL(6, 2),
  total_score DECIMAL(8, 2),
  `rank` INT,
  source VARCHAR(50) DEFAULT 'manual',
  last_synced_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(competition_id, learner_id),
  FOREIGN KEY (competition_id) REFERENCES competitions(id) ON DELETE CASCADE,
  FOREIGN KEY (learner_id) REFERENCES learners(id) ON DELETE CASCADE
);

ALTER TABLE competition_results ADD COLUMN result_stage VARCHAR(50) DEFAULT 'final';

ALTER TABLE competition_results ADD COLUMN learner_grade VARCHAR(50);

ALTER TABLE competition_results ADD COLUMN competition_type VARCHAR(50) DEFAULT 'quiz';

ALTER TABLE competition_results DROP CHECK competition_results_result_stage_check;

