UPDATE learners l
  JOIN users u
  SET user_id = u.id
  WHERE l.user_id IS NULL
  AND u.role = 'learner'
  AND u.school_id = l.school_id
  AND u.full_name = l.full_name;

CREATE TABLE IF NOT EXISTS ai_settings (
  id INT PRIMARY KEY DEFAULT 1 CHECK (id = 1),
  is_enabled TINYINT(1) NOT NULL DEFAULT FALSE,
  enabled_roles JSON NOT NULL DEFAULT ('{}'),
  default_provider_key VARCHAR(50),
  fallback_provider_key VARCHAR(50),
  max_requests_per_hour INT NOT NULL DEFAULT 50,
  max_tokens_per_hour INT NOT NULL DEFAULT 100000,
  max_requests_per_day INT NOT NULL DEFAULT 250,
  max_tokens_per_day INT NOT NULL DEFAULT 500000,
  retain_prompt_days INT NOT NULL DEFAULT 0,
  debug_logging_enabled TINYINT(1) NOT NULL DEFAULT FALSE,
  updated_by_user_id INT,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (updated_by_user_id) REFERENCES users(id) ON DELETE SET NULL
);

CREATE TABLE IF NOT EXISTS ai_providers (
  id INT AUTO_INCREMENT PRIMARY KEY,
  provider_key VARCHAR(50) UNIQUE NOT NULL,
  display_name VARCHAR(120) NOT NULL,
  base_url TEXT,
  api_key_ciphertext TEXT,
  default_model VARCHAR(120),
  fallback_model VARCHAR(120),
  is_enabled TINYINT(1) NOT NULL DEFAULT FALSE,
  is_default TINYINT(1) NOT NULL DEFAULT FALSE,
  config JSON NOT NULL DEFAULT ('{}'),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS ai_role_limits (
  role VARCHAR(30) PRIMARY KEY,
  is_enabled TINYINT(1) NOT NULL DEFAULT FALSE,
  requests_per_hour INT NOT NULL DEFAULT 10,
  tokens_per_hour INT NOT NULL DEFAULT 20000,
  requests_per_day INT NOT NULL DEFAULT 40,
  tokens_per_day INT NOT NULL DEFAULT 80000,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS school_ai_settings (
  school_id INT PRIMARY KEY,
  is_enabled TINYINT(1) NOT NULL DEFAULT FALSE,
  school_admin_enabled TINYINT(1) NOT NULL DEFAULT TRUE,
  teacher_enabled TINYINT(1) NOT NULL DEFAULT FALSE,
  learner_enabled TINYINT(1) NOT NULL DEFAULT FALSE,
  notes TEXT,
  updated_by_user_id INT,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (school_id) REFERENCES schools(id) ON DELETE CASCADE,
  FOREIGN KEY (updated_by_user_id) REFERENCES users(id) ON DELETE SET NULL
);

CREATE TABLE IF NOT EXISTS ai_usage_logs (
  id INT AUTO_INCREMENT PRIMARY KEY,
  user_id INT,
  school_id INT,
  role VARCHAR(30),
  provider_key VARCHAR(50),
  model VARCHAR(120),
  feature VARCHAR(80),
  activity_id INT,
  prompt_tokens INT NOT NULL DEFAULT 0,
  completion_tokens INT NOT NULL DEFAULT 0,
  total_tokens INT NOT NULL DEFAULT 0,
  estimated_cost DECIMAL(12, 6) NOT NULL DEFAULT 0,
  status VARCHAR(30) NOT NULL DEFAULT 'pending',
  error_message TEXT,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (school_id) REFERENCES schools(id) ON DELETE SET NULL
);

